local MushroomForager = {}
local PRODUCTS = {
    common_field_mushroom_basket = { name = "Košarica poljskih gob", woodCost = 1, time = 3, cost = 35, food = 10, happiness = 1, description = "Košarica navadnih poljskih gob za kuhinjo." },
    forest_chanterelle_crate = { name = "Zaboj lisičk", woodCost = 1, time = 5, cost = 80, food = 18, happiness = 1, prestige = 1, description = "Zaboj gozdnih lisičk za plemiško kuhinjo." },
    dried_porcini_jar = { name = "Posušene jurčki", woodCost = 1, glassCost = 1, time = 8, cost = 180, food = 30, prestige = 3, happiness = 2, description = "Posušeni jurčki v steklenem kozarcu za zimo." },
    truffle_collection = { name = "Zbirka tartufov", woodCost = 2, glassCost = 1, silverCost = 1, time = 12, cost = 600, food = 50, prestige = 12, happiness = 4, description = "Redki tartufi v srebrnem ohišju za visoke plemiče." },
    gold_dusted_mushroom = { name = "Zlatoprašni gobe", woodCost = 2, glassCost = 2, goldCost = 1, silverCost = 1, time = 16, cost = 1400, food = 80, prestige = 22, happiness = 6, description = "Gobe posute z zlatim prahom za visoko plemstvo." },
    royal_myco_collection = { name = "Kraljevski myco muzej", woodCost = 3, glassCost = 4, goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, time = 23, cost = 3500, food = 130, prestige = 55, happiness = 12, description = "Veliki kraljevski muzej gob z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    forager_hut = { name = "Gobarjeva koča", cost = { gold = 180, wood = 120, stone = 60 }, upkeep = 4, qualityBonus = 5 },
    drying_loft = { name = "Sušilnica", cost = { gold = 700, wood = 240, stone = 180, glass = 6 }, upkeep = 16, qualityBonus = 18 },
    mycology_lab = { name = "Mikološki laboratorij", cost = { gold = 2000, wood = 360, stone = 480, silver = 28, glass = 14 }, upkeep = 48, qualityBonus = 30 },
    royal_myco_palace = { name = "Kraljevska mikološka palača", cost = { gold = 8500, wood = 580, stone = 720, gold = 50, jewel = 14, glass = 30 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 50 },
}
MushroomForager.woodStock = 16; MushroomForager.glassStock = 8; MushroomForager.silverStock = 6; MushroomForager.goldStock = 6; MushroomForager.jewelStock = 4; MushroomForager.pearlStock = 4
MushroomForager.productStock = {}; MushroomForager.buildings = {}; MushroomForager.maker = nil; MushroomForager.activeMaking = {}; MushroomForager.totalProducts = 0; MushroomForager.dayTimer = 0
function MushroomForager.init() MushroomForager.woodStock=16; MushroomForager.glassStock=8; MushroomForager.silverStock=6; MushroomForager.goldStock=6; MushroomForager.jewelStock=4; MushroomForager.pearlStock=4; MushroomForager.productStock={}; MushroomForager.buildings={}; MushroomForager.maker=nil; MushroomForager.activeMaking={}; MushroomForager.totalProducts=0; MushroomForager.dayTimer=0; print("[MushroomForager] Royal Mushroom Forager System initialized (6 products, 4 buildings)") end
function MushroomForager.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MushroomForager.maker={name=n or ("Gobar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gobar najet: %s (spretnost: %d)",MushroomForager.maker.name,s),"success") end; return true end
function MushroomForager.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MushroomForager.build(id) local ok,e=MushroomForager.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MushroomForager.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MushroomForager.getQualityBonus() local b=0; for _,bd in ipairs(MushroomForager.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MushroomForager.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and MushroomForager.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.glassCost and MushroomForager.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and MushroomForager.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MushroomForager.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MushroomForager.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MushroomForager.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MushroomForager.buildings==0 then return false,"Potrebna gobarjeva koča" end; if not MushroomForager.maker then return false,"Potreben gobar" end; return true end
function MushroomForager.make(pt,qty) qty=qty or 1; local ok,e=MushroomForager.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then MushroomForager.woodStock=MushroomForager.woodStock-d.woodCost*qty end; if d.glassCost then MushroomForager.glassStock=MushroomForager.glassStock-d.glassCost*qty end; if d.silverCost then MushroomForager.silverStock=MushroomForager.silverStock-d.silverCost*qty end; if d.goldCost then MushroomForager.goldStock=MushroomForager.goldStock-d.goldCost*qty end; if d.jewelCost then MushroomForager.jewelStock=MushroomForager.jewelStock-d.jewelCost*qty end; if d.pearlCost then MushroomForager.pearlStock=MushroomForager.pearlStock-d.pearlCost*qty end; local t=d.time; if MushroomForager.maker then t=math.max(1,t-math.floor(MushroomForager.maker.skill/13)) end; table.insert(MushroomForager.activeMaking,{id="mushroom_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nabiranje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MushroomForager.completeMaking(m) local q=1.0+(MushroomForager.getQualityBonus()/100); if MushroomForager.maker then q=q+(MushroomForager.maker.skill/150) end; q=math.min(2.4,q); MushroomForager.productStock[m.productType]=(MushroomForager.productStock[m.productType] or 0)+m.quantity; MushroomForager.totalProducts=MushroomForager.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MushroomForager.maker then MushroomForager.maker.itemsMade=MushroomForager.maker.itemsMade+m.quantity; if math.random()<0.25 then MushroomForager.maker.skill=math.min(100,MushroomForager.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nabira končan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mushroom.harvested",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function MushroomForager.update(dt) if not _G.state then return end; MushroomForager.dayTimer=MushroomForager.dayTimer+dt; if MushroomForager.dayTimer>=30 then MushroomForager.dayTimer=0; for i=#MushroomForager.activeMaking,1,-1 do local m=MushroomForager.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MushroomForager.completeMaking(m); table.remove(MushroomForager.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MushroomForager.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MushroomForager.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MushroomForager.getStats() return {woodStock=MushroomForager.woodStock,glassStock=MushroomForager.glassStock,silverStock=MushroomForager.silverStock,goldStock=MushroomForager.goldStock,jewelStock=MushroomForager.jewelStock,pearlStock=MushroomForager.pearlStock,productStock=MushroomForager.productStock,numBuildings=#MushroomForager.buildings,hasMaker=MushroomForager.maker~=nil,makerName=MushroomForager.maker and MushroomForager.maker.name or "—",makerSkill=MushroomForager.maker and MushroomForager.maker.skill or 0,activeMaking=#MushroomForager.activeMaking,totalProducts=MushroomForager.totalProducts} end
return MushroomForager
